  function syncTimeline(){const total=C.totalDuration(project.scenes);$('#seek').max=total;$('#seek').value=Math.min(time,total);$('#time').textContent=`${C.formatTime(time)} / ${C.formatTime(total)}`;const list=$('#scenes');list.replaceChildren();project.scenes.forEach((s,i)=>{const b=document.createElement('button');b.className='scene'+(i===active?' active':'');b.type='button';const name=document.createElement('strong');name.textContent=`${i+1} · ${s.shotTitle||C.templates.find(t=>t.id===s.template)?.name||'Escena'}`;const small=document.createElement('small');small.textContent=`${s.duration} s · ${s.baseName||s.headline||'Producto'}`;b.append(name,small);b.onclick=()=>{pause();active=i;time=project.scenes.slice(0,i).reduce((v,s)=>v+s.duration,0)+.8*s.duration;syncForm();draw();};list.append(b);});$('#deleteScene').disabled=project.scenes.length<=1;$('#addScene').disabled=project.scenes.length>=12;}
  function asset(src,isVideo=false){if(!src)return null;if(media.has(src))return media.get(src);if(/^data:image\/gif/i.test(src)){const item={complete:false};item._ready=T.gifAsset(src).then(value=>Object.assign(item,value));media.set(src,item);return item;}let item;if(isVideo){item=document.createElement('video');item.src=src;item.preload='auto';item.playsInline=true;item.muted=true;item.loop=true;item.load();item._ready=new Promise((resolve,reject)=>{if(item.readyState>=2)resolve(item);else{item.addEventListener('loadeddata',()=>resolve(item),{once:true});item.addEventListener('error',()=>reject(new Error('No se pudo abrir un clip de video. Probá con MP4 H.264 o WebM.')),{once:true});}});}else{item=new Image();item.src=src;item._ready=item.decode().then(()=>item).catch(()=>{throw new Error('No se pudo abrir una imagen. Usá PNG, JPG o WebP.');});}media.set(src,item);return item;}
  async function prepareMedia(){const jobs=[];for(const s of project.scenes)for(const key of ['base','stamp','final','background','video','back'])if(s[key])jobs.push(asset(s[key],key==='video'||key==='background'&&isVideoSource(s[key]))._ready);if(project.logo)jobs.push(asset(project.logo)._ready);await Promise.all(jobs);await prepareComponents();await setupAudioElements();}
  function fitRect(img,x,y,w,h){const iw=img.videoWidth||img.naturalWidth||img.width,ih=img.videoHeight||img.naturalHeight||img.height;const scale=Math.min(w/iw,h/ih);return{x:x+(w-iw*scale)/2,y:y+(h-ih*scale)/2,w:iw*scale,h:ih*scale};}
  function drawFit(c,img,r){c.drawImage(img,r.x,r.y,r.w,r.h);}
  function roundRect(c,x,y,w,h,r=12){c.beginPath();c.roundRect(x,y,w,h,r);}
  function demoProduct(c,r){c.save();const x=r.x+r.w*.12,y=r.y+r.h*.09,w=r.w*.76,h=r.h*.82;c.shadowColor='#0005';c.shadowBlur=24;c.fillStyle='#efeae0';c.beginPath();c.moveTo(x+w*.28,y);c.lineTo(x+w*.08,y+h*.08);c.lineTo(x-w*.13,y+h*.27);c.lineTo(x+w*.02,y+h*.39);c.lineTo(x+w*.13,y+h*.29);c.lineTo(x+w*.13,y+h);c.quadraticCurveTo(x+w*.5,y+h*1.02,x+w*.87,y+h);c.lineTo(x+w*.87,y+h*.29);c.lineTo(x+w*.98,y+h*.39);c.lineTo(x+w*1.13,y+h*.27);c.lineTo(x+w*.92,y+h*.08);c.lineTo(x+w*.72,y);c.quadraticCurveTo(x+w*.5,y+h*.16,x+w*.28,y);c.closePath();c.fill();c.shadowBlur=0;c.strokeStyle='#d4cdbf';c.lineWidth=2;c.stroke();c.beginPath();c.moveTo(x+w*.28,y);c.quadraticCurveTo(x+w*.5,y+h*.19,x+w*.72,y);c.stroke();c.restore();return{x,y,w,h};}
  function demoStamp(c,b){c.save();c.textAlign='center';c.fillStyle='#b58c38';c.font='bold 45px Georgia';c.fillText('CREER',b.x+b.w/2,b.y+b.h*.35);c.font='26px Georgia';c.fillText('AMAR · CREAR',b.x+b.w/2,b.y+b.h*.48);c.strokeStyle='#b58c38';c.lineWidth=2;c.beginPath();c.moveTo(b.x+b.w*.2,b.y+b.h*.6);c.lineTo(b.x+b.w*.8,b.y+b.h*.6);c.stroke();c.restore();}
  let lastGeometry=null;
  function revealPath(c,b,p,rows){if(p>=1){c.rect(b.x-4,b.y-4,b.w+8,b.h+8);return;}const pos=C.pencilPoint(p,b,rows),rh=b.h/rows;if(pos.row>0)c.rect(b.x-2,b.y-2,b.w+4,rh*pos.row+3);const width=b.w*pos.fraction,x=pos.row%2?b.x+b.w-width:b.x;c.rect(x-2,b.y+pos.row*rh-2,width+4,rh+4);}
  function drawPencil(c,x,y,label,brush=false){c.save();c.translate(x,y);c.rotate(-.55);c.shadowColor='#0003';c.shadowBlur=8;c.fillStyle=brush?'#8f416b':'#e2b44e';roundRect(c,-193,-15,165,30,7);c.fill();c.shadowBlur=0;c.fillStyle=brush?'#b7adb2':'#d5b998';c.beginPath();c.moveTo(-28,-15);c.lineTo(0,0);c.lineTo(-28,15);c.closePath();c.fill();c.fillStyle=brush?'#5b303d':'#232126';c.beginPath();c.moveTo(-10,-5);c.lineTo(0,0);c.lineTo(-10,5);c.closePath();c.fill();c.fillStyle='#fff4fb';roundRect(c,-205,-15,15,30,5);c.fill();c.fillStyle=brush?'#fff0f7':'#382617';c.font='bold 18px Arial';c.textAlign='center';c.textBaseline='middle';c.fillText('SALMOS',-110,1,130);c.restore();}
  function wrapText(c,text,width){const words=String(text||'').split(/\s+/),lines=[];let line='';for(const word of words){const t=line?line+' '+word:word;if(line&&c.measureText(t).width>width){lines.push(line);line=word;}else line=t;}if(line)lines.push(line);return lines;}
  function paintText(c,text,x,y,width,size,color,maxLines=3){if(!text)return 0;let lines;for(let n=size;n>=12;n--){c.font=`${project.italic?'italic ':''}${project.bold?'bold ':''}${n}px "${project.font}", Arial`;lines=wrapText(c,text,width);if(lines.length<=maxLines&&lines.every(l=>c.measureText(l).width<=width)){size=n;break;}}c.fillStyle=color;c.textAlign='center';c.textBaseline='top';for(let i=0;i<lines.length;i++){if(project.outline){c.strokeStyle='#151515';c.lineWidth=4;c.lineJoin='round';c.strokeText(lines[i],x,y+i*size*1.15);}c.fillText(lines[i],x,y+i*size*1.15);}return lines.length*size*1.15;}
  function sceneImage(s){return s.video?asset(s.video,true):s.base?asset(s.base):s.final?asset(s.final):null;}
  function dimensions(width=720){const [rw,rh]=project.ratio.split(':').map(Number);return{w:width,h:Math.round(width*rh/rw/2)*2};}
  function draw(){if(!project)return;const d=dimensions(exporting?canvas.width:720);if(canvas.width!==d.w||canvas.height!==d.h){canvas.width=d.w;canvas.height=d.h;}const at=C.sceneAt(project.scenes,time);if(!at)return;ctx.clearRect(0,0,d.w,d.h);paintScene(ctx,at.scene,at.progress,d.w,d.h,!exporting&&$('#guides').checked);if(at.index>0&&at.local<.32&&project.transition!=='cut'){const alpha=1-C.ease(at.local/.32);if(project.transition==='white'){ctx.fillStyle=`rgba(255,255,255,${alpha})`;ctx.fillRect(0,0,d.w,d.h);}else{ctx.save();ctx.globalAlpha=alpha;paintScene(ctx,project.scenes[at.index-1],1,d.w,d.h,false);ctx.restore();}}$('#seek').value=time;$('#time').textContent=`${C.formatTime(time)} / ${C.formatTime(C.totalDuration(project.scenes))}`;}
  async function setupAudioElements(){for(const kind of ['music','voice']){const src=project.audio[kind],previous=kind==='music'?musicAudio:voiceAudio;if(previous?.getAttribute('src')===src)continue;if(previous){previous.pause();const old=kind==='music'?musicNode:voiceNode;old?.source.disconnect();old?.gain.disconnect();old?.bass?.disconnect();old?.treble?.disconnect();}if(!src){if(kind==='music')musicAudio=null;else voiceAudio=null;continue;}const a=new Audio(src);a.preload='auto';if(kind==='music'){musicAudio=a;musicNode=null;}else{voiceAudio=a;voiceNode=null;}await new Promise((resolve,reject)=>{a.onended=()=>{a._knownDuration=a.currentTime;};if(a.readyState>=1)resolve();else{a.addEventListener('loadedmetadata',resolve,{once:true});a.addEventListener('error',()=>reject(new Error('Ese audio no pudo abrirse. Probá con MP3 o WAV.')),{once:true});}});}}
  function connectAudio(){if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();audioDestination=audioCtx.createMediaStreamDestination();master=audioCtx.createDynamicsCompressor();master.threshold.value=-8;master.knee.value=8;master.ratio.value=4;master.connect(audioDestination);master.connect(audioCtx.destination);}if(musicAudio&&!musicNode){const source=audioCtx.createMediaElementSource(musicAudio),gain=audioCtx.createGain();source.connect(gain);gain.connect(master);musicNode={source,gain};}if(voiceAudio&&!voiceNode){const source=audioCtx.createMediaElementSource(voiceAudio),gain=audioCtx.createGain(),bass=audioCtx.createBiquadFilter(),treble=audioCtx.createBiquadFilter();bass.type='lowshelf';bass.frequency.value=180;treble.type='highshelf';treble.frequency.value=2800;source.connect(bass);bass.connect(treble);treble.connect(gain);gain.connect(master);voiceNode={source,gain,bass,treble};}for(const s of project.scenes)if(s.video){const video=asset(s.video,true);if(!videoNodes.has(video)){const source=audioCtx.createMediaElementSource(video),gain=audioCtx.createGain();source.connect(gain);gain.connect(master);videoNodes.set(video,{source,gain});}}return audioCtx.resume();}
  function syncOneAudio(audio,position,enabled){if(!audio)return;if(!enabled){audio.pause();return;}if(Number.isFinite(audio.duration)&&audio.duration>0){position=C.clamp(position,0,Math.max(0,audio.duration-.03));}if(Math.abs(audio.currentTime-position)>.25)audio.currentTime=position;if(audio.paused)audio.play().catch(()=>{});}
  function syncSound(){const a=project.audio,total=C.totalDuration(project.scenes),voicePosition=(time-a.voiceOffset)*C.clamp(a.voiceRate??1,.6,1.6),voiceActive=!!voiceAudio&&voicePosition>=0&&(voicePosition<(Number.isFinite(voiceAudio.duration)?voiceAudio.duration:(voiceAudio._knownDuration||Infinity))),fade=Math.min(1,time/.3,(total-time)/.5);if(musicAudio){const duration=Number.isFinite(musicAudio.duration)?musicAudio.duration:0,start=C.clamp(a.musicStart,0,Math.max(0,duration-.05)),end=a.musicEnd>start?Math.min(a.musicEnd,duration):duration,length=Math.max(.05,end-start),enabled=a.musicLoop||time<length;syncOneAudio(musicAudio,start+(a.musicLoop?time%length:time),enabled);if(musicNode)musicNode.gain.gain.setTargetAtTime(a.musicVolume*(a.duck&&voiceActive?.6:1)*Math.max(0,fade),audioCtx.currentTime,.03);}if(voiceAudio){voiceAudio.playbackRate=C.clamp(a.voiceRate??1,.6,1.6);voiceAudio.preservesPitch=true;}if(voiceNode){voiceNode.bass.gain.value=C.clamp(a.voiceBass??0,-12,12);voiceNode.treble.gain.value=C.clamp(a.voiceTreble??0,-12,12);}syncOneAudio(voiceAudio,Math.max(0,voicePosition),voiceActive);if(voiceNode)voiceNode.gain.gain.setTargetAtTime(a.voiceVolume*Math.max(0,fade),audioCtx.currentTime,.03);const at=C.sceneAt(project.scenes,time);for(const s of project.scenes)if(s.video){const v=asset(s.video,true),isActive=s===at?.scene;if(isActive){v.muted=!a.clipAudio;if(Number.isFinite(v.duration)&&v.duration>0&&Math.abs(v.currentTime-at.local%v.duration)>.3)v.currentTime=at.local%v.duration;if(v.paused)v.play().catch(()=>{});}else v.pause();const node=videoNodes.get(v);if(node)node.gain.gain.value=isActive&&a.clipAudio?1:0;}for(const s of project.scenes)if(isVideoSource(s.background)){const v=asset(s.background,true),isActive=s===at?.scene;v.muted=true;if(isActive){if(Number.isFinite(v.duration)&&v.duration>0&&Math.abs(v.currentTime-at.local%v.duration)>.25)v.currentTime=at.local%v.duration;if(v.paused)v.play().catch(()=>{});}else v.pause();}}
  function stopSound(){$$('audio').forEach(a=>a.pause());musicAudio?.pause();voiceAudio?.pause();for(const value of media.values())if(value instanceof HTMLVideoElement)value.pause();}
  async function play(){if(playing||exporting)return;try{$$('audio').forEach(a=>a.pause());await prepareMedia();await connectAudio();if(time>=C.totalDuration(project.scenes)-.03)time=0;playing=true;startClock=performance.now()-time*1000;$('#play').textContent='❚❚ Pausar';tick();}catch(e){notify(e.message,'error');}}
  function pause(){playing=false;cancelAnimationFrame(frameId);$('#play').textContent='▶ Ver reel';stopSound();}
  function tick(){if(!playing)return;time=(performance.now()-startClock)/1000;const total=C.totalDuration(project.scenes);if(time>=total){time=total;pause();draw();return;}syncSound();draw();frameId=requestAnimationFrame(tick);}
  async function fileData(file,kind='image'){if(!file)throw new Error('Elegí un archivo.');const max=kind==='video'?80:kind==='audio'?40:24;if(file.size>max*1024*1024)throw new Error(`El archivo supera ${max} MB. Usá uno más liviano para este editor.`);if(kind==='image'&&!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw new Error('Usá PNG, JPG, WebP o GIF; para un fondo animado también podés cargar MP4.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.readAsDataURL(file);});}
  async function setFile(file,kind){pause();const video=kind==='video'||kind==='background'&&file?.type.startsWith('video/');const data=await fileData(file,video?'video':'image');await asset(data,video)._ready;checkpoint();const s=current();s[kind]=data;if(kind!=='background')s.demo=false;if(kind==='background')s.bgMotion='';if(kind==='stamp'){await addPrint(data,file.name);s.stamp=null;syncForm();return;}if(['base','stamp','final'].includes(kind))s.video=null;if(kind==='base'){s.components=[];s.baseName=file.name;s.final=null;s.bounds=null;}if(kind==='stamp'){s.stampName=file.name;s.final=null;s.bounds=null;}if(kind==='final'){s.components=[];s.stamp=null;s.base=null;s.bounds=null;s.baseName=file.name;s.template='clean';editingStamp=false;}if(kind==='video'){s.components=[];editingStamp=false;s.template='clean';s.base=null;s.stamp=null;s.final=null;s.bounds=null;s.baseName=file.name;}syncForm();changed();}
