  let lastExportURL=null;
  function showExportDownload(blob,name){if(lastExportURL)URL.revokeObjectURL(lastExportURL);lastExportURL=URL.createObjectURL(blob);let link=$('#lastExport');if(!link){link=document.createElement('a');link.id='lastExport';link.className='button primary';link.style.margin='6px 0';$('#previewHint').before(link);}link.href=lastExportURL;link.download=name;link.textContent='↓ Descargar último video';link.click();}
