  const filename=()=>String(project.title||'SALMOS-reel').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/gi,'-').slice(0,70);
  async function poster(final=false){if(final)return productFrame();pause();await prepareMedia();const previous=time,oldEdit=editingStamp;editingStamp=false;if(final){const at=C.sceneAt(project.scenes,time);time=at.start+at.scene.duration*.95;}draw();await new Promise(resolve=>canvas.toBlob(blob=>{if(blob)download(blob,filename()+(final?'-para-IA':'-imagen')+'.png');resolve();},'image/png'));time=previous;editingStamp=oldEdit;draw();}
  function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('salmos-reels-v1',1);r.onupgradeneeded=()=>{r.result.createObjectStore('projects',{keyPath:'id'});r.result.createObjectStore('posts',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
  async function dbAction(store,mode,action){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction(store,mode),r=action(tx.objectStore(store));tx.oncomplete=()=>{database.close();resolve(r?.result);};tx.onerror=()=>{database.close();reject(tx.error);};});}
  async function saveRecord(id=project.id){const copy=structuredClone(project);if(musicTrial)Object.assign(copy.audio,musicTrial);await dbAction('projects','readwrite',store=>store.put({...copy,id,originalId:project.id,savedAt:Date.now()}));}
  async function loadSaved(){const all=await dbAction('projects','readonly',s=>s.getAll()),host=$('#savedProjects');host.replaceChildren();all.sort((a,b)=>b.savedAt-a.savedAt).forEach(p=>{const row=document.createElement('div');row.className='saved-card';const title=document.createElement('strong');title.textContent=(p.id==='autosave'?'Borrador automático · ':'')+p.title;const small=document.createElement('p');small.className='hint';small.textContent=`${p.scenes.length} escena(s) · ${new Date(p.savedAt).toLocaleString('es-AR')}`;const open=document.createElement('button');open.textContent='Abrir';open.onclick=async()=>{pause();checkpoint();project={...p,id:p.originalId||p.id};normalizeProject();active=0;time=0;await prepareMedia();syncForm();setTab('editor');draw();};const del=document.createElement('button');del.textContent='Eliminar copia';del.onclick=async()=>{if(!confirm('¿Eliminar esta copia guardada?'))return;await dbAction('projects','readwrite',s=>s.delete(p.id));loadSaved();};row.append(title,small,open,del);host.append(row);});if(!all.length)host.textContent='Todavía no guardaste proyectos.';}
