  async function toggleRecord(){if(recording){recording.stop();return;}if(exporting)return;pause();try{recordStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recording=new MediaRecorder(recordStream,type?{mimeType:type}:{});const chunks=[];recording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recording.onstop=async()=>{const mime=recording.mimeType;recordStream.getTracks().forEach(t=>t.stop());recording=null;recordStream=null;$('#record').textContent='● Grabar mi voz';$('#recordState').textContent='Grabación terminada.';try{checkpoint();project.audio.voice=await blobData(new Blob(chunks,{type:mime}));project.audio.voiceName='Mi voz · '+new Date().toLocaleTimeString('es-AR');await setupAudioElements();syncForm();changed();}catch(e){notify(e.message,'error');}};recording.onerror=()=>{recordStream?.getTracks().forEach(t=>t.stop());recording=null;$('#record').textContent='● Grabar mi voz';notify('La grabación se interrumpió. Revisá el permiso del micrófono.','error');};recording.start(250);$('#record').textContent='■ Terminar grabación';$('#recordState').textContent='Grabando… hablá cerca del micrófono.';}catch(e){notify('No se pudo abrir el micrófono. Permití su uso en el navegador o subí una grabación.','error');}}
  async function doExport(){if(musicTrial)return notify('Terminá la prueba musical y elegí una pista antes de exportar.');if(exporting||recording)return notify('Terminá la grabación antes de exportar.','error');const desired=$('#exportFormat').value,width=Number($('#quality').value),mp4='video/mp4;codecs=avc1.42E01E,mp4a.40.2',mp4Only='video/mp4;codecs=avc1.42001E,mp4a.40.2',webm='video/webm;codecs=vp9,opus',fallback='video/webm;codecs=vp8,opus';if(!window.MediaRecorder||!canvas.captureStream)return notify('Este navegador no permite exportar video. Usá una versión actual de Chrome o Edge.','error');const hasAudio=!!(project.audio.music||project.audio.voice||project.audio.clipAudio);const mp4Type=[mp4,mp4Only,...(hasAudio?[]:['video/mp4;codecs=avc1.42E01E'])].find(t=>MediaRecorder.isTypeSupported(t));if(desired==='mp4'&&!mp4Type&&(!localReady||!localHealth?.ffmpeg)){setTab('audio');$('#exportDialog').close();return notify('Para MP4 en este navegador, abrí el programa local y tocá «Conectar programa local». También podés exportar WebM.','error');}const mime=desired!=='webm'&&mp4Type?mp4Type:[webm,fallback,'video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)return notify('No hay un formato de grabación disponible en este navegador.','error');pause();$('#exportDialog').close();const oldTime=time;let stream,recorder;try{await prepareMedia();await connectAudio();exporting=true;cancelled=false;document.body.classList.add('exporting');$('#busyOverlay').hidden=false;$('#busyText').textContent='Creando tu video…';$('#exportProgress').value=0;const d=dimensions(width);canvas.width=d.w;canvas.height=d.h;time=0;draw();stream=canvas.captureStream(30);if(project.audio.music||project.audio.voice||project.audio.clipAudio)for(const track of audioDestination.stream.getAudioTracks())stream.addTrack(track.clone());const chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:width>=1080?12000000:width>=720?6500000:3500000,audioBitsPerSecond:192000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};const stopped=new Promise((resolve,reject)=>{recorder.onstop=resolve;recorder.onerror=e=>reject(new Error(e.error?.message||'Falló la grabación.'));});recorder.start(500);const start=performance.now()+500,duration=C.totalDuration(project.scenes);await new Promise(resolve=>{function frame(){if(cancelled){resolve();return;}time=Math.max(0,Math.min(duration,(performance.now()-start)/1000));if(performance.now()>=start)syncSound();draw();$('#exportProgress').value=time/duration;if(performance.now()-start>=(duration*1000+250)){resolve();return;}requestAnimationFrame(frame);}requestAnimationFrame(frame);});stopSound();if(recorder.state!=='inactive')recorder.stop();await stopped;if(cancelled)return;let blob=new Blob(chunks,{type:recorder.mimeType}),extension=recorder.mimeType.startsWith('video/mp4')?'mp4':'webm';if(desired==='mp4'&&extension!=='mp4'){$('#busyText').textContent='Convirtiendo a MP4 en tu computadora…';blob=await(await helperFetch('/api/convert',{method:'POST',headers:{'Content-Type':blob.type},body:blob})).blob();extension='mp4';}showExportDownload(blob,filename()+'.'+extension);notify(`Video ${extension.toUpperCase()} descargado con ${project.scenes.length} escena(s).`);}catch(e){notify(e.message||'No se pudo exportar. Probá con calidad 540 o 720.','error');}finally{stopSound();if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());exporting=false;$('#busyOverlay').hidden=true;document.body.classList.remove('exporting');time=oldTime;draw();syncUndo();}}
