  async function importPayload(payload){pause();const read=async value=>value instanceof Blob?blobData(value):value||null;const base=await read(payload.base),final=await read(payload.final);if(!base&&!final)throw new Error('Esta vista no tiene imagen.');const components=[];for(const l of payload.components||[])components.push({...l,src:await read(l.src)});checkpoint();const s=current();Object.assign(s,{base,final,stamp:null,video:null,background:await read(payload.background),backgroundName:payload.backgroundName||'',back:await read(payload.back),components,sourceProductId:payload.productId||null,sourceViewKey:payload.viewKey||'',baseName:payload.name||'Producto de SALMOS',shotTitle:payload.name||'',demo:false,source:payload.source||'salmos',template:'clean',headline:'',detail:'',cta:'',bounds:null,bgMotion:''});if(components.length){components[0].fx='pencil';components[0].effect={start:.1,length:1.6,soft:.5};}selectedComponent=components[0]?.id||null;await prepareMedia();time=project.scenes.slice(0,active).reduce((v,s)=>v+s.duration,0);syncForm();changed();setTab('editor');notify(components.length?'Vista recibida con '+components.length+' capas. Se conservan medidas y superficie de Producción.':'Foto final recibida. Podés agregar textos y efectos de escena.');}

